$ {
  let activeIndex = 0;
}

<div>
  <div role="tablist">
    <for|tab, i| of=input.tab>
      <button
        aria-selected=(i === activeIndex ? "true" : undefined)
        on-click() {
          activeIndex = i;
        }
      >
        ${tab.label}
      </button>
    </for>
  </div>

  <div id="panel">
    ${input.tab[activeIndex]?.renderBody()}
  </div>

  <@slot name="tab" label />
</div>

